import React, {
  useState,
  useEffect,
  useMemo,
  useCallback,
  useRef,
} from "react";
import "../styles/Home.css";
import {
  characterAPI,
  campaignAPI,
  factionAPI,
  npcAPI,
  siteStatsAPI,
  transformBackendToFrontend,
} from "../features/character-sheet";
import { getUserAvatarSrc } from "../utils/homeAvatar";
import { useAuth } from "../features/auth";
import { PATCH_NOTES } from "../data/patchNotes";
import {
  flattenPatchNotesPreview,
  sortPatchNotesEntries,
} from "../utils/patchNotesPreview";
import {
  buildSessionScatterPoints,
  buildBarChartRows,
} from "../utils/homeChartData";
import {
  visibleCampaignsForHome,
  visibleCharactersForHome,
  visibleNpcsForHome,
  buildGmFactionGroupsForHome,
  isCampaignGmForUser,
  visibleFactionGroupsForHome,
} from "../utils/homeCampaignSort";
import {
  HOME_CARD_GRID_FALLBACK_COLUMNS,
  homeCardGridColumnCount,
} from "../utils/homeCardGrid";
import HomeSessionScatterChart from "../components/home/HomeSessionScatterChart";
import HomeStatsBarChart from "../components/home/HomeStatsBarChart";
import HomeStandCoin from "../components/home/HomeStandCoin";
import HomeFactionInlineEditor from "../components/home/HomeFactionInlineEditor";
import HomeCampaignCard from "../components/home/HomeCampaignCard";
import HomeCharacterCard from "../components/home/HomeCharacterCard";
import HomeNpcCard from "../components/home/HomeNpcCard";
import HomeFactionCard from "../components/home/HomeFactionCard";
import ConfirmDeleteModal from "../components/ConfirmDeleteModal";
import { buildRouteHref, handleSpaNavClick } from "../utils/spaNavigation";

/** Hero “tradition” pills: short blurbs for home only (not rules text). */
const HERO_PILLS = [
  {
    key: "stand",
    label: "Stand",
    className: "pill-stand",
    description:
      "Stand users manifest a fighting spirit as its own being with bizarre rules. You roll parallel Stand-coin dice on Power, Speed, Precision, and Durability.",
  },
  {
    key: "hamon",
    label: "Hamon",
    className: "pill-hamon",
    description:
      "Hamon users shape breathing-trained life energy—ripple—for strikes, defense, and sensing. It is the disciplined human path when you want power without a Stand partner.",
  },
  {
    key: "spin",
    label: "Spin",
    className: "pill-spin",
    description:
      "Spin users apply the Golden Rectangle through Steel Balls and similar tools: mastered rotation bends trajectories and wounds until geometry itself becomes the weapon.",
  },
];

function getUserDisplayName(person) {
  const username = person?.username;
  return typeof username === "string" && username.trim()
    ? username.trim()
    : "Unknown";
}

/** How long the undo banner stays before the DELETE hits the API. */
const HOME_DELETE_UNDO_MS = 10000;

const HomePage = ({
  onToggleMenu,
  onSearch,
  onOpenAccountMenu,
  menuOpen = false,
  onNavigateToCharacter,
  onNavigateToCampaign,
  onNavigateToRules,
  onNavigateToPatchNotes,
  onNavigateToLicenses,
  onNavigateToNPC,
}) => {
  const { user } = useAuth();
  const [characters, setCharacters] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [campaigns, setCampaigns] = useState([]);
  const [campaignsLoading, setCampaignsLoading] = useState(true);
  const [invitations, setInvitations] = useState([]);
  /** Latest deferred home delete (character or NPC) while Undo is available. */
  const [pendingDelete, setPendingDelete] = useState(null);
  const pendingDeleteRef = useRef(null);
  const pendingDeleteTimerRef = useRef(null);
  /** Confirm gate before PC/NPC undo-queue or faction hard delete. */
  const [deleteConfirm, setDeleteConfirm] = useState(null);
  const [deleteConfirmBusy, setDeleteConfirmBusy] = useState(false);
  const [invitationsLoading, setInvitationsLoading] = useState(true);
  const [invitationBusyId, setInvitationBusyId] = useState(null);
  const [invitationError, setInvitationError] = useState(null);
  const [npcs, setNpcs] = useState([]);
  const [npcsLoading, setNpcsLoading] = useState(true);
  const [siteStats, setSiteStats] = useState(null);
  const [siteStatsLoading, setSiteStatsLoading] = useState(true);
  const [openHeroPill, setOpenHeroPill] = useState(null);
  const [expandedFactionId, setExpandedFactionId] = useState(null);
  const [showAllCharacters, setShowAllCharacters] = useState(false);
  const [showAllCampaigns, setShowAllCampaigns] = useState(false);
  const [showAllNpcs, setShowAllNpcs] = useState(false);
  const [showAllFactions, setShowAllFactions] = useState(false);
  const splitLeftRef = useRef(null);
  const [cardPreviewLimit, setCardPreviewLimit] = useState(
    HOME_CARD_GRID_FALLBACK_COLUMNS,
  );

  useEffect(() => {
    const el = splitLeftRef.current;
    if (!el || typeof ResizeObserver === "undefined") return undefined;

    const update = () => {
      setCardPreviewLimit(homeCardGridColumnCount(el.clientWidth));
    };
    update();
    const observer = new ResizeObserver(update);
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  const loadCharacters = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const backendCharacters = await characterAPI.getCharacters({ mine: true });
      const frontendCharacters = (backendCharacters || []).map(
        transformBackendToFrontend,
      );
      setCharacters(frontendCharacters);
    } catch (err) {
      console.error("Failed to load characters:", err);
      setError(err.message);
      setCharacters([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!user) {
      setCharacters([]);
      setLoading(false);
      setError(null);
      return;
    }
    loadCharacters();
  }, [user, loadCharacters]);

  useEffect(() => {
    if (!user) {
      setSiteStats(null);
      setSiteStatsLoading(false);
      return undefined;
    }
    let cancelled = false;
    setSiteStatsLoading(true);
    siteStatsAPI
      .getSiteStats()
      .then((data) => {
        if (!cancelled && data && typeof data === "object") setSiteStats(data);
      })
      .catch(() => {
        if (!cancelled) setSiteStats(null);
      })
      .finally(() => {
        if (!cancelled) setSiteStatsLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [user]);

  useEffect(() => {
    if (!user) {
      setCampaigns([]);
      setCampaignsLoading(false);
      setInvitations([]);
      setInvitationsLoading(false);
      setInvitationError(null);
      setNpcs([]);
      setNpcsLoading(false);
      return;
    }
    setCampaignsLoading(true);
    setInvitationsLoading(true);
    campaignAPI
      .getCampaigns()
      .then((list) => setCampaigns(Array.isArray(list) ? list : []))
      .catch(() => setCampaigns([]))
      .finally(() => setCampaignsLoading(false));

    campaignAPI
      .getInvitations()
      .then((list) => setInvitations(Array.isArray(list) ? list : []))
      .catch(() => setInvitations([]))
      .finally(() => setInvitationsLoading(false));

    setNpcsLoading(true);
    npcAPI
      .getNPCs(undefined, { mine: true })
      .then((list) => setNpcs(Array.isArray(list) ? list : []))
      .catch(() => setNpcs([]))
      .finally(() => setNpcsLoading(false));
  }, [user]);

  const patchRows = useMemo(
    () => flattenPatchNotesPreview(sortPatchNotesEntries(PATCH_NOTES), 7),
    [],
  );

  const liveStats = useMemo(
    () => ({
      activeCampaigns: siteStats?.active_campaigns ?? 0,
      sessionCount: siteStats?.session_count ?? 0,
      crewCount: siteStats?.crew_count ?? 0,
      pcCount: siteStats?.pc_count ?? 0,
      npcCount: siteStats?.npc_count ?? 0,
    }),
    [siteStats],
  );

  const sessionScatter = useMemo(
    () => buildSessionScatterPoints(campaigns),
    [campaigns],
  );
  const { visible: visibleCampaigns, hiddenCount: hiddenCampaignCount } =
    useMemo(
      () =>
        visibleCampaignsForHome(campaigns, { expanded: showAllCampaigns }),
      [campaigns, showAllCampaigns],
    );
  const { visible: visibleCharacters, hiddenCount: hiddenCharacterCount } =
    useMemo(
      () =>
        visibleCharactersForHome(characters, campaigns, {
          expanded: showAllCharacters,
          limit: cardPreviewLimit,
        }),
      [characters, campaigns, showAllCharacters, cardPreviewLimit],
    );
  const { visible: visibleNpcs, hiddenCount: hiddenNpcCount } = useMemo(
    () =>
      visibleNpcsForHome(npcs, campaigns, {
        expanded: showAllNpcs,
        limit: cardPreviewLimit,
      }),
    [npcs, campaigns, showAllNpcs, cardPreviewLimit],
  );
  const barChartRows = useMemo(() => buildBarChartRows(liveStats), [liveStats]);
  const barChartLoading = siteStatsLoading;

  const playbookLine = useMemo(() => {
    const pc = siteStats?.playbook_counts;
    if (!pc) return "—";
    return `Stand ${pc.STAND ?? 0} · Hamon ${pc.HAMON ?? 0} · Spin ${pc.SPIN ?? 0}`;
  }, [siteStats]);

  const topHeritagesLine = useMemo(() => {
    const list = siteStats?.top_heritages;
    if (!Array.isArray(list) || list.length === 0) return "—";
    return list.map((h) => `${h.name} (${h.count})`).join(", ");
  }, [siteStats]);

  const gmFactionGroups = useMemo(
    () => buildGmFactionGroupsForHome(campaigns, user?.id),
    [campaigns, user?.id],
  );
  const { visible: visibleFactionGroups, hiddenCount: hiddenFactionCount } =
    useMemo(
      () =>
        visibleFactionGroupsForHome(gmFactionGroups, {
          expanded: showAllFactions,
          limit: cardPreviewLimit,
        }),
      [gmFactionGroups, showAllFactions, cardPreviewLimit],
    );

  useEffect(() => {
    if (expandedFactionId == null) return;
    const stillVisible = visibleFactionGroups.some((g) =>
      g.factions.some((f) => f.id === expandedFactionId),
    );
    if (!stillVisible) setExpandedFactionId(null);
  }, [visibleFactionGroups, expandedFactionId]);

  const firstGmCampaignId = useMemo(() => {
    if (!user) return null;
    const gm = (campaigns || []).find((c) =>
      isCampaignGmForUser(c, user.id),
    );
    return gm?.id ?? null;
  }, [campaigns, user]);

  const clearPendingDeleteTimer = useCallback(() => {
    if (pendingDeleteTimerRef.current != null) {
      clearTimeout(pendingDeleteTimerRef.current);
      pendingDeleteTimerRef.current = null;
    }
  }, []);

  const commitPendingDelete = useCallback(async () => {
    const pending = pendingDeleteRef.current;
    clearPendingDeleteTimer();
    pendingDeleteRef.current = null;
    setPendingDelete(null);
    if (!pending?.item?.id) return;
    try {
      if (pending.kind === "character") {
        await characterAPI.deleteCharacter(pending.item.id);
      } else if (pending.kind === "npc") {
        await npcAPI.deleteNPC(pending.item.id);
      }
    } catch (err) {
      console.error("Failed to delete:", err);
      if (pending.kind === "character") {
        setCharacters((prev) => {
          if (prev.some((c) => c.id === pending.item.id)) return prev;
          return [...prev, pending.item];
        });
        setError(err.message || "Failed to delete character");
      } else if (pending.kind === "npc") {
        setNpcs((prev) => {
          if (prev.some((n) => n.id === pending.item.id)) return prev;
          return [...prev, pending.item];
        });
      }
    }
  }, [clearPendingDeleteTimer]);

  const undoPendingDelete = useCallback(() => {
    const pending = pendingDeleteRef.current;
    clearPendingDeleteTimer();
    pendingDeleteRef.current = null;
    setPendingDelete(null);
    if (!pending?.item) return;
    if (pending.kind === "character") {
      setCharacters((prev) => {
        if (prev.some((c) => c.id === pending.item.id)) return prev;
        return [...prev, pending.item];
      });
    } else if (pending.kind === "npc") {
      setNpcs((prev) => {
        if (prev.some((n) => n.id === pending.item.id)) return prev;
        return [...prev, pending.item];
      });
    }
  }, [clearPendingDeleteTimer]);

  const queueHomeDelete = useCallback(
    async (kind, item) => {
      if (!item?.id) return;
      if (pendingDeleteRef.current) {
        await commitPendingDelete();
      }
      const label =
        kind === "character"
          ? item.name || item.true_name || `Character ${item.id}`
          : item.name || item.stand_name || `NPC ${item.id}`;
      if (kind === "character") {
        setCharacters((prev) => prev.filter((c) => c.id !== item.id));
      } else {
        setNpcs((prev) => prev.filter((n) => n.id !== item.id));
      }
      const next = { kind, item, label };
      pendingDeleteRef.current = next;
      setPendingDelete(next);
      clearPendingDeleteTimer();
      pendingDeleteTimerRef.current = setTimeout(() => {
        commitPendingDelete();
      }, HOME_DELETE_UNDO_MS);
    },
    [clearPendingDeleteTimer, commitPendingDelete],
  );

  useEffect(() => {
    return () => {
      // Leaving Home: finalize any deferred delete so it is not orphaned.
      const pending = pendingDeleteRef.current;
      if (pendingDeleteTimerRef.current != null) {
        clearTimeout(pendingDeleteTimerRef.current);
        pendingDeleteTimerRef.current = null;
      }
      if (pending?.item?.id) {
        if (pending.kind === "character") {
          characterAPI.deleteCharacter(pending.item.id).catch(() => null);
        } else if (pending.kind === "npc") {
          npcAPI.deleteNPC(pending.item.id).catch(() => null);
        }
      }
      pendingDeleteRef.current = null;
    };
  }, []);

  const handleCreateCharacter = () => {
    if (typeof onNavigateToCharacter === "function")
      onNavigateToCharacter(null);
  };

  const handleEditCharacter = (character) => {
    if (typeof onNavigateToCharacter === "function" && character?.id)
      onNavigateToCharacter(character.id);
  };

  const handleDeleteCharacter = (characterId) => {
    const item = characters.find((c) => c.id === characterId);
    if (!item) return;
    const label = item.name || item.true_name || `Character ${item.id}`;
    setDeleteConfirm({
      kind: "character",
      item,
      label,
      message: `Delete character “${label}”? You can undo for a short time after.`,
    });
  };

  const handleManageCampaign = (campaignId) => {
    if (typeof onNavigateToCampaign === "function")
      onNavigateToCampaign(campaignId);
  };

  const handleAcceptCampaignInvitation = async (invitationId) => {
    setInvitationError(null);
    setInvitationBusyId(invitationId);
    try {
      await campaignAPI.acceptInvitation(invitationId);
      setInvitations((prev) => prev.filter((inv) => inv.id !== invitationId));
      const list = await campaignAPI.getCampaigns();
      setCampaigns(Array.isArray(list) ? list : []);
    } catch (err) {
      setInvitationError(err.message || "Could not accept invitation");
    } finally {
      setInvitationBusyId(null);
    }
  };

  const handleDeclineCampaignInvitation = async (invitationId) => {
    setInvitationError(null);
    setInvitationBusyId(invitationId);
    try {
      await campaignAPI.declineInvitation(invitationId);
      setInvitations((prev) => prev.filter((inv) => inv.id !== invitationId));
    } catch (err) {
      setInvitationError(err.message || "Could not decline invitation");
    } finally {
      setInvitationBusyId(null);
    }
  };

  const handleEditNpc = (npcId) => {
    if (typeof onNavigateToNPC === "function" && npcId) onNavigateToNPC(npcId);
  };

  const handleDeleteNpc = (npcId) => {
    const item = npcs.find((n) => n.id === npcId);
    if (!item) return;
    const label = item.name || item.stand_name || `NPC ${item.id}`;
    setDeleteConfirm({
      kind: "npc",
      item,
      label,
      message: `Delete NPC “${label}”? You can undo for a short time after.`,
    });
  };

  const refreshCampaigns = useCallback(() => {
    setCampaignsLoading(true);
    return campaignAPI
      .getCampaigns()
      .then((list) => setCampaigns(Array.isArray(list) ? list : []))
      .catch(() => setCampaigns([]))
      .finally(() => setCampaignsLoading(false));
  }, []);

  const handleDeleteFaction = (factionId) => {
    const faction =
      (campaigns || [])
        .flatMap((c) => c.factions || [])
        .find((f) => f.id === factionId) || null;
    const name = faction?.name || "this faction";
    setDeleteConfirm({
      kind: "faction",
      factionId,
      label: name,
      message: `Delete faction “${name}”?`,
    });
  };

  const handleConfirmDelete = useCallback(async () => {
    if (!deleteConfirm) return;
    const pending = deleteConfirm;
    if (pending.kind === "character" || pending.kind === "npc") {
      setDeleteConfirm(null);
      await queueHomeDelete(pending.kind, pending.item);
      return;
    }
    if (pending.kind === "faction") {
      setDeleteConfirmBusy(true);
      try {
        await factionAPI.deleteFaction(pending.factionId);
        if (expandedFactionId === pending.factionId) setExpandedFactionId(null);
        refreshCampaigns();
        setDeleteConfirm(null);
      } catch (err) {
        console.error("Failed to delete faction:", err);
      } finally {
        setDeleteConfirmBusy(false);
      }
    }
  }, [deleteConfirm, expandedFactionId, queueHomeDelete, refreshCampaigns]);

  const handleFactionEditorSaved = () => {
    setExpandedFactionId(null);
    refreshCampaigns();
  };

  const handleFactionEditorDeleted = (factionId) => {
    if (expandedFactionId === factionId) setExpandedFactionId(null);
    refreshCampaigns();
  };

  return (
    <div className="home-poc">
      <header className="site-header">
        <div className="header-inner">
          <div className="header-left">
            <button
              type="button"
              className={`hamburger${menuOpen ? " open" : ""}`}
              onClick={onToggleMenu}
              aria-label="Open menu"
            >
              <span />
              <span />
              <span />
            </button>
            <a href="#/" className="logo" onClick={(e) => e.preventDefault()}>
              <span className="logo-part1">1(800)</span>
              <span className="logo-part2">BIZARRE</span>
            </a>
          </div>
          <div className="header-right">
            <button
              type="button"
              className="header-btn header-btn-ghost"
              onClick={onSearch}
            >
              Search
            </button>
            <div className="account-wrapper">
              <button
                type="button"
                className="header-btn header-btn-fill"
                onClick={onOpenAccountMenu}
              >
                Account
              </button>
            </div>
          </div>
        </div>
      </header>

      <section className="hero">
        <div className="hero-inner">
          <div className="hero-text">
            <div className="hero-headline-group fade-up d1">
              <h1 className="hero-title">
                <span className="hero-title-stand">STAND</span>
                <br />
                <span className="accent">PROUD.</span>
              </h1>
              <div className="hero-pill-stack">
                <div
                  className="hero-pills"
                  role="group"
                  aria-label="Playstyle traditions"
                >
                  {HERO_PILLS.map(({ key, label, className }) => {
                    const isOpen = openHeroPill === key;
                    return (
                      <button
                        key={key}
                        id={`hero-pill-btn-${key}`}
                        type="button"
                        className={`pill ${className}${isOpen ? " is-selected" : ""}`}
                        aria-expanded={isOpen}
                        aria-controls="hero-pill-description"
                        onClick={() =>
                          setOpenHeroPill((cur) => (cur === key ? null : key))
                        }
                      >
                        {label}
                      </button>
                    );
                  })}
                </div>
                <div
                  id="hero-pill-description"
                  className={`hero-pill-panel${openHeroPill ? " is-open" : ""}`}
                  role="region"
                  aria-hidden={!openHeroPill}
                  aria-labelledby={
                    openHeroPill ? `hero-pill-btn-${openHeroPill}` : undefined
                  }
                >
                  <div className="hero-pill-panel-inner">
                    {openHeroPill ? (
                      <p className="hero-pill-panel-text" key={openHeroPill}>
                        {
                          HERO_PILLS.find((p) => p.key === openHeroPill)
                            ?.description
                        }
                      </p>
                    ) : null}
                  </div>
                </div>
              </div>
            </div>
            <p className="hero-subtext fade-up d2">
              Fate is truly a very long, roundabout path...
            </p>
            <div className="hero-cta fade-up d3">
              <a
                href={buildRouteHref("character")}
                className="btn btn-primary"
                onClick={(e) => handleSpaNavClick(e, handleCreateCharacter)}
              >
                + Create Character
              </a>
              <a
                href={buildRouteHref("rules")}
                className="btn btn-secondary"
                onClick={(e) => handleSpaNavClick(e, onNavigateToRules)}
              >
                Game Rules
              </a>
            </div>
          </div>
          <div className="hero-coin-column fade-up d3">
            <HomeStandCoin />
          </div>
        </div>
      </section>

      <section className="split">
        <div className="split-left" ref={splitLeftRef}>
          <div className="split-label">Player</div>
          <div className="split-action-bar">
            <div className="split-title">Your Characters</div>
            <button
              type="button"
              className="split-btn"
              onClick={handleCreateCharacter}
            >
              + New
            </button>
          </div>

          {pendingDelete ? (
            <div className="home-undo-delete" role="status">
              <span className="home-undo-delete-text">
                Deleted “{pendingDelete.label}”
              </span>
              <button
                type="button"
                className="home-undo-delete-btn"
                onClick={undoPendingDelete}
              >
                Undo
              </button>
            </div>
          ) : null}

          {loading ? (
            <p className="home-muted">Loading characters…</p>
          ) : error ? (
            <p className="home-error">
              {error}{" "}
              <button
                type="button"
                className="split-btn"
                onClick={loadCharacters}
              >
                Retry
              </button>
            </p>
          ) : characters.length === 0 ? null : (
            <>
              {showAllCharacters ? (
                <button
                  type="button"
                  className="home-show-more home-show-more-light"
                  onClick={() => setShowAllCharacters(false)}
                  aria-expanded={true}
                >
                  - show less -
                </button>
              ) : null}
              <div className="home-card-grid">
                {visibleCharacters.map((character) => (
                  <HomeCharacterCard
                    key={character.id}
                    character={character}
                    onEdit={handleEditCharacter}
                    onDelete={handleDeleteCharacter}
                  />
                ))}
              </div>
              {(hiddenCharacterCount > 0 || showAllCharacters) && (
                <button
                  type="button"
                  className="home-show-more home-show-more-light"
                  onClick={() => setShowAllCharacters((v) => !v)}
                  aria-expanded={showAllCharacters}
                >
                  {showAllCharacters ? "- show less -" : "- show more -"}
                </button>
              )}
            </>
          )}

          {!loading && !error && characters.length === 0 && (
            <p className="home-muted">No characters yet.</p>
          )}

          <div className="split-divider">
            <div className="split-divider-bar" />
            <span className="split-divider-label">Your NPCs</span>
            <div className="split-divider-bar" />
          </div>
          <div className="split-npc-row">
            <div className="split-label">Game Master</div>
            <button
              type="button"
              className="split-btn split-btn-purple"
              onClick={() => onNavigateToNPC?.(null)}
            >
              + New NPC
            </button>
          </div>

          {npcsLoading ? (
            <p className="home-muted">Loading NPCs…</p>
          ) : npcs.length === 0 ? (
            <p className="home-muted">No NPCs yet.</p>
          ) : (
            <>
              {showAllNpcs ? (
                <button
                  type="button"
                  className="home-show-more home-show-more-light"
                  onClick={() => setShowAllNpcs(false)}
                  aria-expanded={true}
                >
                  - show less -
                </button>
              ) : null}
              <div className="home-card-grid">
                {visibleNpcs.map((npc) => (
                  <HomeNpcCard
                    key={npc.id}
                    npc={npc}
                    onEdit={handleEditNpc}
                    onDelete={handleDeleteNpc}
                  />
                ))}
              </div>
              {(hiddenNpcCount > 0 || showAllNpcs) && (
                <button
                  type="button"
                  className="home-show-more home-show-more-light"
                  onClick={() => setShowAllNpcs((v) => !v)}
                  aria-expanded={showAllNpcs}
                >
                  {showAllNpcs ? "- show less -" : "- show more -"}
                </button>
              )}
            </>
          )}
        </div>

        <div className="split-right">
          <div className="split-label">Campaigns</div>
          <div className="split-action-bar">
            <div className="split-title">Your Campaigns</div>
            <button
              type="button"
              className="split-btn"
              onClick={() => onNavigateToCampaign?.(null)}
            >
              + New Campaign
            </button>
          </div>

          {invitationError && (
            <p className="home-invite-error" role="alert">
              {invitationError}
            </p>
          )}

          {!invitationsLoading &&
            invitations.filter((inv) => inv.status === "pending").map((inv) => {
              const gm = inv.gm;
              const crew = Array.isArray(inv.players) ? inv.players : [];
              const gmName = getUserDisplayName(gm);
              const gmAvatarSrc = getUserAvatarSrc(gm);
              const desc = String(inv.campaign_description || "").trim();
              const busy = invitationBusyId === inv.id;

              return (
                <div key={inv.id} className="g-invite-card" role="group" aria-label="Campaign invitation">
                  <div className="g-card-stripe" />
                  <div className="g-card-body">
                    <div className="g-card-info">
                      <div className="g-card-header">
                        <div className="g-card-name">{inv.campaign_name || "—"}</div>
                        <div className="g-card-badges">
                          <span className="g-badge g-badge-invite">Invite</span>
                        </div>
                      </div>
                      <div className="g-card-gm-row">
                        <span className="g-card-gm-label">GM</span>
                        <div className="g-card-gm-chip">
                          <span className="g-card-user-avatar" aria-hidden="true">
                            {gmAvatarSrc ? (
                              <img src={gmAvatarSrc} alt="" />
                            ) : (
                              gmName.charAt(0).toUpperCase()
                            )}
                          </span>
                          <span className="g-card-user-name">{gmName}</span>
                        </div>
                      </div>
                      {desc ? <div className="g-card-desc">{desc}</div> : null}
                      <div className="g-invite-section-label">Crew</div>
                      <div className="g-card-player-list">
                        {crew.length === 0 ? (
                          <span className="g-card-player-empty">No players yet</span>
                        ) : (
                          crew.map((player) => {
                            const playerName = getUserDisplayName(player);
                            const playerAvatarSrc = getUserAvatarSrc(player);
                            return (
                              <span
                                key={player.id || playerName}
                                className="g-card-player-chip"
                              >
                                <span className="g-card-user-avatar" aria-hidden="true">
                                  {playerAvatarSrc ? (
                                    <img src={playerAvatarSrc} alt="" />
                                  ) : (
                                    playerName.charAt(0).toUpperCase()
                                  )}
                                </span>
                                <span className="g-card-user-name">{playerName}</span>
                              </span>
                            );
                          })
                        )}
                      </div>
                      <div className="g-invite-actions">
                        <button
                          type="button"
                          className="split-btn g-invite-btn-accept"
                          disabled={busy}
                          onClick={() => handleAcceptCampaignInvitation(inv.id)}
                        >
                          {busy ? "…" : "Accept"}
                        </button>
                        <button
                          type="button"
                          className="g-invite-btn-decline"
                          disabled={busy}
                          onClick={() => handleDeclineCampaignInvitation(inv.id)}
                        >
                          Decline
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}

          {campaignsLoading ? (
            <p className="home-muted-dark">Loading campaigns…</p>
          ) : campaigns.length === 0 ? (
            <p className="home-muted-dark">No campaigns yet.</p>
          ) : (
            <>
              {showAllCampaigns ? (
                <button
                  type="button"
                  className="home-show-more home-show-more-dark"
                  onClick={() => setShowAllCampaigns(false)}
                  aria-expanded={true}
                >
                  - show less -
                </button>
              ) : null}
              {visibleCampaigns.map((campaign) => (
                <HomeCampaignCard
                  key={campaign.id}
                  campaign={campaign}
                  href={buildRouteHref("campaigns", {
                    campaignId: campaign.id,
                  })}
                  onClick={(e) =>
                    handleSpaNavClick(e, () =>
                      handleManageCampaign(campaign.id),
                    )
                  }
                  isGm={Boolean(user && isCampaignGmForUser(campaign, user.id))}
                  user={user}
                />
              ))}
              {(hiddenCampaignCount > 0 || showAllCampaigns) && (
                <button
                  type="button"
                  className="home-show-more home-show-more-dark"
                  onClick={() => setShowAllCampaigns((v) => !v)}
                  aria-expanded={showAllCampaigns}
                >
                  {showAllCampaigns ? "- show less -" : "- show more -"}
                </button>
              )}
            </>
          )}

          <div className="split-divider">
            <div className="split-divider-bar" />
            <span className="split-divider-label">Your Factions</span>
            <div className="split-divider-bar" />
          </div>

          {gmFactionGroups.length === 0 ? (
            <>
              <div className="split-npc-row">
                <div>
                  <div className="split-label">Factions</div>
                </div>
                {firstGmCampaignId != null ? (
                  <button
                    type="button"
                    className="split-btn split-btn-amber"
                    onClick={() => onNavigateToCampaign?.(firstGmCampaignId)}
                  >
                    + New Faction
                  </button>
                ) : null}
              </div>
              <p className="home-muted-dark">No factions yet.</p>
            </>
          ) : (
            <>
              {showAllFactions ? (
                <button
                  type="button"
                  className="home-show-more home-show-more-dark"
                  onClick={() => setShowAllFactions(false)}
                  aria-expanded={true}
                >
                  - show less -
                </button>
              ) : null}
              {visibleFactionGroups.map(({ campaign, factions }) => (
              <React.Fragment key={campaign.id}>
                <div className="split-npc-row">
                  <div>
                    <div className="split-label">{campaign.name}</div>
                  </div>
                  <button
                    type="button"
                    className="split-btn split-btn-amber"
                    onClick={() => onNavigateToCampaign?.(campaign.id)}
                  >
                    + New Faction
                  </button>
                </div>
                <div className="home-card-grid home-faction-grid">
                  {factions.map((f) => {
                    const isExpanded = expandedFactionId === f.id;
                    const toggleExpanded = () =>
                      setExpandedFactionId(isExpanded ? null : f.id);
                    return (
                      <React.Fragment key={f.id}>
                        <HomeFactionCard
                          faction={f}
                          isExpanded={isExpanded}
                          onToggle={toggleExpanded}
                          onDelete={handleDeleteFaction}
                        />
                        {isExpanded ? (
                          <div className="f-edit-span">
                            <HomeFactionInlineEditor
                              faction={f}
                              campaign={campaign}
                              onCancel={() => setExpandedFactionId(null)}
                              onSaved={handleFactionEditorSaved}
                              onDeleted={handleFactionEditorDeleted}
                            />
                          </div>
                        ) : null}
                      </React.Fragment>
                    );
                  })}
                </div>
              </React.Fragment>
              ))}
              {(hiddenFactionCount > 0 || showAllFactions) && (
                <button
                  type="button"
                  className="home-show-more home-show-more-dark"
                  onClick={() => setShowAllFactions((v) => !v)}
                  aria-expanded={showAllFactions}
                >
                  {showAllFactions ? "- show less -" : "- show more -"}
                </button>
              )}
            </>
          )}
        </div>
      </section>

      <div className="quick-strip">
        <a
          href={buildRouteHref("character")}
          className="qa"
          onClick={(e) => handleSpaNavClick(e, handleCreateCharacter)}
          style={{ textDecoration: "none", color: "inherit" }}
        >
          <div className="qa-icon">+</div>
          <div className="qa-title">Create Character</div>
          <div className="qa-desc">Build your next Stand user.</div>
          <div className="qa-arrow">→</div>
        </a>
        <a
          href={buildRouteHref("campaigns")}
          className="qa"
          onClick={(e) => handleSpaNavClick(e, () => onNavigateToCampaign?.(null))}
          style={{ textDecoration: "none", color: "inherit" }}
        >
          <div className="qa-icon">☆</div>
          <div className="qa-title">Join Campaign</div>
          <div className="qa-desc">Find other bizarre individuals.</div>
          <div className="qa-arrow">→</div>
        </a>
        <a
          href={buildRouteHref("rules")}
          className="qa"
          onClick={(e) => handleSpaNavClick(e, onNavigateToRules)}
          style={{ textDecoration: "none", color: "inherit" }}
        >
          <div className="qa-icon">♦</div>
          <div className="qa-title">Game Rules</div>
          <div className="qa-desc">Master the SRD mechanics.</div>
          <div className="qa-arrow">→</div>
        </a>
        <a
          href={buildRouteHref("campaigns")}
          className="qa"
          onClick={(e) => handleSpaNavClick(e, () => onNavigateToCampaign?.(null))}
          style={{ textDecoration: "none", color: "inherit" }}
        >
          <div className="qa-icon">✎</div>
          <div className="qa-title">Create Campaign</div>
          <div className="qa-desc">Run your own bizarre adventure.</div>
          <div className="qa-arrow">→</div>
        </a>
      </div>

      <section className="home-stats-section">
        <div className="home-stats-inner">
          <div className="hero-art fade-up d3">
            <div className="hero-art-ghost">VOL.1</div>
            <div className="hero-stats">
              <div className="hero-stats-title">Live Stats</div>
              <div className="hero-stat-row">
                <span className="hero-stat-label">
                  <span className="hero-stat-dot hero-stat-dot-green" />
                  Campaigns
                </span>
                <span className="hero-stat-value">
                  {liveStats.activeCampaigns} active
                </span>
              </div>
              <div className="hero-stat-row">
                <span className="hero-stat-label">
                  <span className="hero-stat-dot hero-stat-dot-orange" />
                  PCs / NPCs
                </span>
                <span className="hero-stat-value">
                  {liveStats.pcCount} / {liveStats.npcCount}
                </span>
              </div>
              <div className="hero-stat-row hero-stat-row-tall">
                <span className="hero-stat-label">Stand / Hamon / Spin</span>
                <span className="hero-stat-value hero-stat-value-compact">
                  {playbookLine}
                </span>
              </div>
              <div className="hero-stat-row hero-stat-row-tall">
                <span className="hero-stat-label">Top heritages</span>
                <span className="hero-stat-value hero-stat-value-compact">
                  {topHeritagesLine}
                </span>
              </div>
            </div>
            <HomeSessionScatterChart
              data={sessionScatter}
              loading={campaignsLoading}
            />
            <HomeStatsBarChart data={barChartRows} loading={barChartLoading} />
            <div className="hero-art-label">
              <div className="hero-art-label-title">STAND USERS</div>
              <div className="hero-art-label-sub">
                A Bizarre Adventure TTRPG
              </div>
            </div>
          </div>
        </div>
      </section>

      <section className="patch-section">
        <div className="patch-header">
          <span className="patch-header-title">Recent Changes</span>
          <a
            href={buildRouteHref("patch-notes")}
            className="patch-header-link"
            onClick={(e) => handleSpaNavClick(e, onNavigateToPatchNotes)}
          >
            View all patch notes →
          </a>
        </div>
        <div className="patch-list">
          {patchRows.map((row, i) => (
            <div key={`${row.date}-${i}`} className="patch-entry">
              <div className="patch-date">{row.date}</div>
              <div className="patch-cat">{row.cat}</div>
              <div className="patch-text">{row.text}</div>
            </div>
          ))}
        </div>
      </section>

      <footer className="site-footer">
        <div className="footer-inner">
          <span>
            <span className="footer-logo">1(800)BIZARRE</span>
            <span className="footer-copyright">
              © {new Date().getFullYear()} — Based on Blades in the Dark by
              John Harper (CC BY 3.0)
            </span>
          </span>
          <div className="footer-links">
            <a
              href={buildRouteHref("licenses")}
              className="footer-link"
              onClick={(e) => handleSpaNavClick(e, onNavigateToLicenses)}
            >
              Licenses
            </a>
            <a
              href={buildRouteHref("patch-notes")}
              className="footer-link"
              onClick={(e) => handleSpaNavClick(e, onNavigateToPatchNotes)}
            >
              Patch Notes
            </a>
            <button
              type="button"
              className="footer-link"
              onClick={() => {
                window.location.href =
                  "mailto:?subject=1(800)BIZARRE%20error%20report";
              }}
            >
              Report Error
            </button>
          </div>
        </div>
      </footer>

      <ConfirmDeleteModal
        open={Boolean(deleteConfirm)}
        message={deleteConfirm?.message || ""}
        busy={deleteConfirmBusy}
        onCancel={() => {
          if (!deleteConfirmBusy) setDeleteConfirm(null);
        }}
        onConfirm={handleConfirmDelete}
      />
    </div>
  );
};

export default HomePage;
